WITH p AS (SELECT SOURCE_ID,BATCH_SHA256,ROW_INDEX,ROW_SHA256,TRY_PARSE_JSON(PAYLOAD_JSON) AS p FROM VECTOR_RESEARCH.RAW.SOURCE_RECORDS), b AS (SELECT SOURCE_ID,BATCH_SHA256,p:ticker::STRING AS ticker,p:bar_time_utc::STRING AS bar_time,TRY_TO_DOUBLE(p:close::STRING) AS c,TRY_TO_DOUBLE(p:open::STRING) AS o,TRY_TO_DOUBLE(p:high::STRING) AS h,TRY_TO_DOUBLE(p:low::STRING) AS l,TRY_TO_DOUBLE(p:volume::STRING) AS v FROM p WHERE SOURCE_ID IN ('massive_bars','massive_bars_unadjusted'))
SELECT 'bars' AS SECTION,OBJECT_CONSTRUCT_KEEP_NULL('source',SOURCE_ID,'batch',BATCH_SHA256,'ticker',ticker,'rows',COUNT(*),'unique_times',COUNT(DISTINCT bar_time),'first',MIN(bar_time),'last',MAX(bar_time),'invalid_ohlcv',COUNT_IF(c IS NULL OR o IS NULL OR h IS NULL OR l IS NULL OR v IS NULL OR c<=0 OR o<=0 OR l<=0 OR h<GREATEST(o,c,l) OR l>LEAST(o,c,h) OR v<0)) AS DETAIL FROM b GROUP BY 1,SOURCE_ID,BATCH_SHA256,ticker
UNION ALL SELECT 'macro_coverage',OBJECT_CONSTRUCT_KEEP_NULL('source',SOURCE_ID,'field',f.KEY,'valid_numeric',COUNT(TRY_TO_DOUBLE(f.VALUE::STRING)),'first_valid',MIN(IFF(TRY_TO_DOUBLE(f.VALUE::STRING) IS NOT NULL,p:observation_date::STRING,NULL)),'last_valid',MAX(IFF(TRY_TO_DOUBLE(f.VALUE::STRING) IS NOT NULL,p:observation_date::STRING,NULL))) FROM p,LATERAL FLATTEN(INPUT=>p) f WHERE SOURCE_ID IN ('fred_rates','fred_market','fred_industry') AND f.KEY<>'observation_date' GROUP BY SOURCE_ID,f.KEY
UNION ALL SELECT 'manifest_coverage',OBJECT_CONSTRUCT_KEEP_NULL('source',p.SOURCE_ID,'batch',p.BATCH_SHA256,'rows',COUNT(*),'manifest_entries',COUNT(DISTINCT m.RETRIEVED_AT),'declared_rows',MAX(m.ROW_COUNT)) FROM p LEFT JOIN VECTOR_RESEARCH.RAW.INGESTION_MANIFESTS m ON p.SOURCE_ID=m.SOURCE_ID AND p.BATCH_SHA256=m.BATCH_SHA256 GROUP BY p.SOURCE_ID,p.BATCH_SHA256
